"""
Gerenciador de Pop-ups e Notificações UI do Kael.
Garante que solicitações de permissão e ações pendentes apareçam de forma interativa na interface web.
"""
import json
import logging
from pathlib import Path

logger = logging.getLogger("kael_popups")

class KaelPopupManager:
    def __init__(self, base_dir: Path):
        self.base_dir = base_dir
        self.popup_file = base_dir / "data" / "pending_popups.json"
        self.popup_file.parent.mkdir(parents=True, exist_ok=True)
        if not self.popup_file.exists():
            self._save([])

    def _load(self):
        try:
            if self.popup_file.exists():
                return json.loads(self.popup_file.read_text(encoding="utf-8"))
        except Exception as e:
            logger.error(f"Erro ao ler popups: {e}")
        return []

    def _save(self, items):
        try:
            self.popup_file.write_text(json.dumps(items, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            logger.error(f"Erro ao salvar popups: {e}")

    def criar_popup(self, titulo: str, mensagem: str, acao_id: str = None, tipo: str = "confirmacao"):
        itens = self._load()
        novo = {
            "id": f"pop_{len(itens) + 1}",
            "titulo": titulo,
            "mensagem": mensagem,
            "acao_id": acao_id,
            "tipo": tipo,
            "ativo": True
        }
        itens.append(novo)
        self._save(itens)
        return novo["id"]

    def listar_ativos(self):
        return [p for p in self._load() if p.get("ativo")]

    def fechar_popup(self, popup_id: str):
        itens = self._load()
        for p in itens:
            if p.get("id") == popup_id:
                p["ativo"] = False
        self._save(itens)

def init_popup_manager(base_dir: Path):
    return KaelPopupManager(base_dir)

